import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const CODE_TYPES = ['근로소득', '퇴직소득', '소득공제', '농특세', '지방소득세', '사회보험 정산', '학자금 상환'];
const USE_STATUS = ['사용', '미사용'];

function fail(message: string): never {
  throw new ApiError(400, 'VALIDATION_FAILED', message);
}

function requiredText(value: unknown, label: string, max: number): string {
  if (typeof value !== 'string' || value.trim() === '') {
    fail(label + '을(를) 입력해 주세요.');
  }
  const text = (value as string).trim();
  if (text.length > max) {
    fail(label + '은(는) ' + max + '자 이하로 입력해 주세요.');
  }
  return text;
}

function optionalText(value: unknown, label: string, max: number): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > max) {
    fail(label + ' 형식이 올바르지 않습니다.');
  }
  return value as string;
}

function oneOf(value: unknown, label: string, allowed: string[]): string {
  if (typeof value !== 'string' || !allowed.includes(value)) {
    fail(label + ' 값이 올바르지 않습니다.');
  }
  return value as string;
}

function optionalBool(value: unknown, label: string): boolean | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'boolean') {
    fail(label + ' 형식이 올바르지 않습니다.');
  }
  return value as boolean;
}

@Controller('api/v1')
export class FnSfr02001Controller {
  @Get('/payroll-codes')
  async listPayrollCodes(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const query = checks.queryOf(req.query);
    const codeType = query['codeType'] === undefined || query['codeType'] === '' ? null : oneOf(query['codeType'], '코드 구분', CODE_TYPES);
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    let size = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      fail('page 또는 size 값이 올바르지 않습니다.');
    }
    if (size > 200) {
      size = 200;
    }
    return transaction(async (db) => {
      const params = { codeType, limit: size, offset: page * size };
      const rows = await db.query(
        `SELECT payroll_code_id AS "payrollCodeId", code_type AS "codeType", code AS "code",
                code_name AS "codeName", social_insurance_sum_yn AS "socialInsuranceSumYn",
                use_status AS "useStatus", remark AS "remark"
           FROM payroll_code
          WHERE (CAST(:codeType AS varchar) IS NULL OR code_type = :codeType)
          ORDER BY code_type, code
          LIMIT :limit OFFSET :offset`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM payroll_code
          WHERE (CAST(:codeType AS varchar) IS NULL OR code_type = :codeType)`,
        { codeType },
      );
      return { items: rows, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/payroll-codes')
  @HttpCode(200)
  async createPayrollCode(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const codeType = oneOf(data['codeType'], '코드 구분', CODE_TYPES);
    const code = requiredText(data['code'], '코드', 20);
    const codeName = requiredText(data['codeName'], '코드명', 100);
    const socialInsuranceSumYn = optionalBool(data['socialInsuranceSumYn'], '사회보험 합산 대상 여부');
    const useStatus = oneOf(data['useStatus'], '사용 여부', USE_STATUS);
    const remark = optionalText(data['remark'], '비고', 500);
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT payroll_code_id FROM payroll_code WHERE code_type = :codeType AND code = :code',
        { codeType, code },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'PAYROLL_CODE_DUPLICATED', '같은 코드 구분 안에 동일한 코드가 이미 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO payroll_code
           (code_type, code, code_name, social_insurance_sum_yn, use_status, remark, created_at, updated_at)
         VALUES
           (:codeType, :code, :codeName, :socialInsuranceSumYn, :useStatus, :remark, now(), now())
         RETURNING payroll_code_id AS "payrollCodeId"`,
        { codeType, code, codeName, socialInsuranceSumYn, useStatus, remark },
      );
      return { payrollCodeId: Number(rows[0].payrollCodeId) };
    });
  }

  @Put('/payroll-codes/:payrollCodeId')
  async updatePayrollCode(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const idText = req.params['payrollCodeId'];
    const data = checks.inputOf(req.body);
    const codeName = requiredText(data['codeName'], '코드명', 100);
    const socialInsuranceSumYn = optionalBool(data['socialInsuranceSumYn'], '사회보험 합산 대상 여부');
    const useStatus = oneOf(data['useStatus'], '사용 여부', USE_STATUS);
    const remark = optionalText(data['remark'], '비고', 500);
    if (!/^\d+$/.test(idText)) {
      fail('급여 기초코드 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT payroll_code_id FROM payroll_code WHERE payroll_code_id = CAST(:id AS bigint)',
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PAYROLL_CODE_NOT_FOUND', '급여 기초코드를 찾을 수 없습니다.');
      }
      await db.execute(
        `UPDATE payroll_code
            SET code_name = :codeName,
                social_insurance_sum_yn = :socialInsuranceSumYn,
                use_status = :useStatus,
                remark = :remark,
                updated_at = now()
          WHERE payroll_code_id = CAST(:id AS bigint)`,
        { id: idText, codeName, socialInsuranceSumYn, useStatus, remark },
      );
      return { payrollCodeId: Number(idText) };
    });
  }
}

