import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Filters,
  Form,
  Pager,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const CODE_TYPES: [string, string][] = [
  ['근로소득', '근로소득'],
  ['퇴직소득', '퇴직소득'],
  ['소득공제', '소득공제'],
  ['농특세', '농특세'],
  ['지방소득세', '지방소득세'],
  ['사회보험 정산', '사회보험 정산'],
  ['학자금 상환', '학자금 상환'],
];
const USE_STATUS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];
const YN: [string, string][] = [
  ['Y', '대상'],
  ['N', '비대상'],
];
const SIZE = 20;

interface Editing {
  row: Row | null;
}

function ynOf(value: unknown): string {
  if (value === true) {
    return 'Y';
  }
  if (value === false) {
    return 'N';
  }
  return '';
}

function CodeForm({ role, row, onDone }: { role: string; row: Row | null; onDone: () => void }) {
  const editing = row !== null;
  const [codeType, setCodeType] = useState(editing ? String(row!['codeType']) : '');
  const [code, setCode] = useState(editing ? String(row!['code']) : '');
  const [codeName, setCodeName] = useState(editing ? String(row!['codeName'] ?? '') : '');
  const [yn, setYn] = useState(editing ? ynOf(row!['socialInsuranceSumYn']) : '');
  const [useStatus, setUseStatus] = useState(editing ? String(row!['useStatus']) : '사용');
  const [remark, setRemark] = useState(editing ? String(row!['remark'] ?? '') : '');

  async function submit() {
    if (!editing && !codeType) {
      throw new Error('코드 구분을 선택해 주세요.');
    }
    if (!editing && !code.trim()) {
      throw new Error('코드를 입력해 주세요.');
    }
    if (!codeName.trim()) {
      throw new Error('코드명을 입력해 주세요.');
    }
    if (!useStatus) {
      throw new Error('사용 여부를 선택해 주세요.');
    }
    const body: Row = {
      codeName: codeName.trim(),
      socialInsuranceSumYn: yn === '' ? null : yn === 'Y',
      useStatus,
      remark: remark === '' ? null : remark,
    };
    if (editing) {
      await call('PUT', '/payroll-codes/' + row!['payrollCodeId'], role, body);
    } else {
      await call('POST', '/payroll-codes', role, { ...body, codeType, code: code.trim() });
    }
    onDone();
  }

  return (
    <Form onSubmit={submit} submit={editing ? '수정' : '등록'}>
      <Field label='코드 구분' required={!editing}>
        {editing ? (
          <span>{codeType}</span>
        ) : (
          <Select value={codeType} onChange={setCodeType} options={CODE_TYPES} />
        )}
      </Field>
      <Field label='코드' required={!editing}>
        {editing ? <span>{code}</span> : <TextInput value={code} onChange={setCode} />}
      </Field>
      <Field label='코드명' required>
        <TextInput value={codeName} onChange={setCodeName} />
      </Field>
      <Field label='사회보험 합산 대상 여부'>
        <Select value={yn} onChange={setYn} options={YN} placeholder='해당 없음' />
      </Field>
      <Field label='사용 여부' required>
        <Select value={useStatus} onChange={setUseStatus} options={USE_STATUS} />
      </Field>
      <Field label='비고' wide>
        <TextInput value={remark} onChange={setRemark} multiline />
      </Field>
    </Form>
  );
}

export default function FnSfr02001Page({ role, notify }: PageProps) {
  const [codeType, setCodeType] = useState('');
  const [applied, setApplied] = useState('');
  const [page, setPage] = useState(0);
  const [drawer, setDrawer] = useState<Editing | null>(null);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/payroll-codes', role, undefined, { codeType: applied, page, size: SIZE }),
    [applied, page],
  );

  function search() {
    setPage(0);
    setApplied(codeType);
  }

  function reset() {
    setCodeType('');
    setApplied('');
    setPage(0);
  }

  function done() {
    const wasEditing = drawer !== null && drawer.row !== null;
    setDrawer(null);
    notify(wasEditing ? '급여 기초코드를 수정했습니다.' : '급여 기초코드를 등록했습니다.');
    reload();
  }

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>급여 기초코드</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='코드 구분'>
            <Select value={codeType} onChange={setCodeType} options={CODE_TYPES} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type='button' onClick={() => setDrawer({ row: null })}>
            코드 등록
          </button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          columns={[
            { key: 'codeType', label: '코드 구분' },
            { key: 'code', label: '코드' },
            { key: 'codeName', label: '코드명' },
            {
              key: 'socialInsuranceSumYn',
              label: '사회보험 합산 대상 여부',
              render: (r) => (r['socialInsuranceSumYn'] === true ? '대상' : r['socialInsuranceSumYn'] === false ? '비대상' : '-'),
            },
            { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r['useStatus']} /> },
            { key: 'remark', label: '비고' },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <button type='button' onClick={() => setDrawer({ row: r })}>
                  수정
                </button>
              ),
            },
          ]}
          rows={data?.items ?? []}
          empty='등록된 급여 기초코드가 없습니다.'
        />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {drawer ? (
        <Drawer title={drawer.row ? '급여 기초코드 수정' : '급여 기초코드 등록'} onClose={() => setDrawer(null)}>
          <CodeForm role={role} row={drawer.row} onDone={done} />
        </Drawer>
      ) : null}
    </div>
  );
}
